import math

def s_n(n):
    return n * (n + 1) // 2

def find_closest_square(S):
    if S < 0:
        return None, float('inf')
    root = math.isqrt(S)
    k1_sq = root**2
    k2_sq = (root + 1)**2

    diff1 = abs(S - k1_sq)
    diff2 = abs(S - k2_sq)

    if diff1 <= diff2:
        return k1_sq, diff1
    else:
        return k2_sq, diff2

# Check n from 1 to 50
n_list = list(range(1, 51))
results = []
for n in n_list:
    S = s_n(n)
    k_sq, diff = find_closest_square(S)
    results.append((n, S, k_sq, diff))

# Sort by proximity (smallest difference first)
results.sort(key=lambda x: x[3])

print("n, S_n, Closest Square (k^2), Difference")
for n, S, k_sq, diff in results:
    print(f"{n}, {S}, {k_sq}, {diff}")

print("\nTop 5 candidates by smallest difference:")
for n, S, k_sq, diff in results[:5]:
    print(f"n={n}, S_n={S}, k^2={k_sq}, Diff={diff}")

